<?php require 'config.php';$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();if($count){exit('Admin already exists. Delete this file for safety.');}verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Enter a name, valid email and password of at least 8 characters.';else{$s=$pdo->prepare("INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?,'admin')");$s->execute([$name,$email,'-',password_hash($pass,PASSWORD_DEFAULT)]);echo 'Admin created. Delete setup_admin.php now, then login.';exit;}}
$pageTitle='Create admin';include 'partials/header.php';?><div class="form-card"><h1>First-time admin setup</h1><p>Use this page once only. Delete setup_admin.php after creating the admin account.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required><div class="spacer"></div><button class="btn">Create admin</button></form></div><?php include 'partials/footer.php';?>
